pragma solidity ^0.8.0;

interface IRun {
    struct Status {
        address target;
        bool status;
    }

    function run() external;
    function pauseStatus() external view returns (Status[] memory);
    function isPauser(address) external view returns (bool);
}

contract Main {
    IRun private immutable to;

    /// @notice Emitted when a caller is not allowed to perform an action
    error NotAllowed();

    modifier onlyPausers() {
        if (!to.isPauser(msg.sender)) {
            revert NotAllowed();
        }
        _;
    }

    constructor() {
        to = IRun(msg.sender);
    }

    function run() external onlyPausers {
        to.run();
    }

    function pauseStatus() external view returns (IRun.Status[] memory) {
        return to.pauseStatus();
    }
}
